// The thumbnail every Oversite developer product carries: the Oversite logo
// at 512 by 512, the size Roblox asks for. Roblox will not sell a product on
// its store page without a thumbnail.
export const ROBUX_PRODUCT_THUMB_BASE64 =
  "";
export function robuxProductThumb(): Uint8Array {
  return Uint8Array.from(atob(ROBUX_PRODUCT_THUMB_BASE64), (c) => c.charCodeAt(0));
}
